options.customCss:
:root {
    --font-family: 'Open Sans', sans-serif;
    --font-weight-normal: 400;
    --font-weight-bold: 600;
    --font-size-body: 12px;
    --font-size-label: 14px;
    --font-size-test-notice: 12px;
    --font-size-input: 14px;
    --font-size-header: 20px;
    --font-size-paragraph: 14px;
    --font-size-link: 12px;
    --font-size-error: 12px;
    --font-size-html-h1: 28px;
    --font-size-html-h2: 20px;
    --font-size-html-h3: 16px;
    --font-size-html-h4: 14px;
    --font-size-html-h5: 12px;
    --font-size-html-h6: 10px;
    --font-size-subheader: 14px;

    /* Theme Architecture */
    --color-background: #0d1117;             /* Deep slate background */
    --color-test-notice-text: #111111;        /* Solid black text for clear warning read */
    --color-test-notice-bg: #ffb74d;          /* Vibrant amber backdrop to contrast black text */
    --color-test-notice-border: #443215;      

    --color-card-bg: #161b22;                 /* Elevated container dark canvas */
    --color-card-border: #30363d;             
    --color-card-shadow: rgba(0, 0, 0, 0.4);  

    --color-link: #111111;                    /* Bold black utility links */
    --color-header: #000000;                  /* Pure black header typography */
    --color-header-subtext: #1a1a1a;          /* Dark charcoal secondary text */
    --color-label: #000000;                   /* Strong black form input titles */

    --color-input-border: #30363d;            
    --color-input-text: #111111;              /* Rich black text entry string */
    --color-focus-border: #58a6ff;            

    --color-submit-btn-bg: #ff6d5a;           
    --color-submit-btn-text: #ffffff;         /* Kept clean white for functional visibility against the signature button background */
    --color-clear-button-bg: #30363d;         

    --color-error: #f85149;                   
    --color-required: #ff6d5a;                
    --color-html-text: #000000;               /* Absolute black rendering for markdown or body blocks */
    --color-html-link: #58a6ff;               

    /* Border Radii */
    --border-radius-card: 8px;
    --border-radius-input: 6px;
    --border-radius-clear-btn: 50%;
    --card-border-radius: 8px;

    /* Spacing */
    --padding-container-top: 24px;
    --padding-card: 24px;
    --padding-test-notice-vertical: 12px;
    --padding-test-notice-horizontal: 24px;
    --margin-bottom-card: 16px;
    --padding-form-input: 12px;
    --card-padding: 24px;
    --card-margin-bottom: 16px;

    /* Dimensions */
    --container-width: 448px;
    --submit-btn-height: 48px;
    --checkbox-size: 18px;

    /* Others */
    --box-shadow-card: 0px 4px 16px 0px var(--color-card-shadow);
    --opacity-placeholder: 0.6;               /* Darkened slightly for higher initial text visibility */
}

parameters.jsCode:
// Grab the raw text containing the markdown json block
let rawText = $input.all()[0].json.text;

// Clean out the markdown code fence wrappers if they exist
rawText = rawText.replace(/```json\n?/, '').replace(/```\n?$/, '').trim();

// Parse the cleaned string into a true JavaScript array
const parsedArray = JSON.parse(rawText);

// Map the items back out so n8n processes each scene as an individual row
return parsedArray.map(item => ({ json: item }));

// Get the array of scenes from the incoming data key
const scenes = Object.values($input.all()[0].json.data);

// Build the HTML scaffolding
let htmlOutput = `
<p>Sat Sri Akal! Here is your production sheet for the new Short:</p>

<table border="1" cellpadding="8" style="border-collapse: collapse; width: 100%; font-family: sans-serif;">
  <tr style="background-color: #f2f2f2; text-align: left;">
    <th style="width: 8%;">Scene</th>
    <th style="width: 17%;">Title</th>
    <th style="width: 35%;">What to Say (Hinglish Narration)</th>
    <th style="width: 40%;">Image Prompt (Copy/Paste into Midjourney or DALL-E)</th>
  </tr>
`;

// Loop through each scene and append the rows
for (const item of scenes) {
  htmlOutput += `
  <tr>
    <td>${item.scene}</td>
    <td><strong>${item.title}</strong></td>
    <td style="font-style: italic; color: #333; line-height: 1.4;">"${item.narration}"</td>
    <td style="background-color: #fafafa; font-family: monospace; font-size: 12px; word-break: break-word; color: #555;">${item.image_prompt}</td>
  </tr>
  `;
}

// Close the table formatting
htmlOutput += `
</table>
<p style="margin-top: 20px; color: #666; font-size: 11px;">Automated via n8n pipeline.</p>
`;

// Return the fully built string to the next node
return [{ json: { emailHtmlBody: htmlOutput } }];

